import json, statistics
from pathlib import Path

def summarize(data):
    rows={}
    for case in ('proxy-1k','proxy-16k'):
        rows[case]={}
        for engine in dict.fromkeys(r['engine'] for r in data['runs']):
            runs=[r for r in data['runs'] if r['case']==case and r['engine']==engine]
            groups=[[r for r in runs if r['round']==i] for i in (1,2,3)]
            if not all(len(g)==2 for g in groups):continue
            pairs=[200*abs(g[0]['rps']-g[1]['rps'])/(g[0]['rps']+g[1]['rps']) for g in groups]
            cvs=[100*statistics.stdev(g[n]['rps'] for g in groups)/statistics.mean(g[n]['rps'] for g in groups) for n in (0,1)]
            stats={k:{'median':statistics.median(r[k] for r in runs),'min':min(r[k] for r in runs),'max':max(r[k] for r in runs)} for k in ['rps','server_cpu_us_per_request','p99_ms','peak_pss_kib']}
            rows[case][engine]={'calibration':{'passed':max(pairs+cvs)<=10 and all(r['errors']==0 for r in runs),'pairs_pct':pairs,'cvs_pct':cvs},'stats':stats,'requests':sum(r['requests'] for r in runs),'errors':sum(r['errors'] for r in runs)}
    return rows
if __name__=='__main__':
    import sys
    for file in sys.argv[1:]:
        p=Path(file)
        data=json.loads(p.read_text())
        out=summarize(data)
        p.with_name(p.stem+'-summary.json').write_text(json.dumps(out,indent=2)+'\n')
        print(p.name)
        for case,engines in out.items():
            for engine,r in engines.items():
                s=r['stats']; c=r['calibration']
                print(case,engine,'A/A',c['passed'],'RPS',round(s['rps']['median']),'CPU',round(s['server_cpu_us_per_request']['median'],2),'P99max',s['p99_ms']['max'],'PSSmaxMiB',round(s['peak_pss_kib']['max']/1024,2))
